"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[70651],{6957:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"WeaponPoseDisplay","desc":"Display weapons for the weapon pose editor. On `EquipPoseDisplay(name)` the player\\nholds a script-free copy of that weapon (`WeaponPoseSchema.IsWeapon`), so the editor can\\nshow the hold of any pose weapon, owned or not. `\\"\\"` (or any other name) removes it.\\nThe copy is named `WeaponPoseConfig.DisplayName` with the attribute `PoseOf` = weapon\\nname: the hold code reads it through `HoldAnimConfig.holdName`, and every weapon system\\nthat looks up `WeaponConfig[tool.Name]` ignores it (no fire, no ammo, no aim).\\nIt goes straight into the character and is destroyed when it leaves it (hotbar swap,\\ndeath), so it never lands in the Backpack. Source: `ServerStorage.PoseDisplayWeapons`\\n(Lobby), else `StarterPack` (Game Instance).","realm":["Server"],"source":{"line":16,"path":"src/ServerScriptService/WeaponPoseDisplay.server.luau"}}')}}]);